/* =========================================================
   Mock handlers — REELS · STORIES · HIGHLIGHTS · SOUNDS
   ---------------------------------------------------------
   Every function here returns the WIRE shape the Java
   controller returns, not the view shape the component wants:

     · reels          → FeedItemResponse (postType REEL, videoUrl =
                        the playable clip, mediaUrl = the poster)
     · reel detail    → PostResponse
     · reel comments  → CommentResponse / ReplyResponse
     · stories        → StoryByAuthorEntity  (storyId/storyType/
                        visibility/mediaUrl/thumbnailUrl/textContent)
     · story views    → StoryViewEntity
     · story polls    → StoryPollEntity + CastVoteResult(choice,voteA,voteB)
     · highlights     → HighlightByAuthorEntity / StoryInHighlightEntity
     · sounds         → SoundEntity / SoundByCategoryEntity / PostBySoundEntity

   MEDIA. The fixture stores integers (`clip`, `cover`), not URLs.
   The URLs are built here as self-contained data: URIs — a handful of
   tiny H.264 clips and generated SVG posters — so a reel actually
   PLAYS and a story actually renders offline, with no dependency on a
   host that may not resolve. Keeping the base64 out of data.json also
   keeps the shared fixture readable.

   THERE IS NO STORY-TRAY LIST ENDPOINT (verified in
   CassandraStoryTrayController — it binds /stream and nothing else),
   so the rail in src/lib/storyTray.js fans out over the viewer's
   `following` list and calls /stories/by-author/{id} once per person.
   The `storyTray` fixture key is therefore the PEOPLE index (it also
   supplies the AuthorSummary embedded in every reel/comment row);
   the rail lights up only for authors the users domain reports as
   followed. Keep those eight ids in the following list.
   ========================================================= */
import { page, paging, mockError, seeded } from '../util.js'

/* ---------------------------------------------------------------
   Media. Four ~6 KB H.264 clips (180×320, 8 s, looping gradient) and
   one short tone, inlined so nothing here reaches the network.
   --------------------------------------------------------------- */
const CLIPS = [
  'data:video/mp4;base64,',
  'data:video/mp4;base64,',
  'data:video/mp4;base64,',
  'data:video/mp4;base64,',
]

const TONE = 'data:audio/mpeg;base64,'

/* Oxford-blue-family cover palettes: [from, to, ink]. `cover` in the
   fixture is a 1-based index into this list. */
const PALETTE = [
  ['#002147', '#1f4e7e', '#b9d6f2'],
  ['#101d2b', '#3f6d5a', '#cfe3d6'],
  ['#241826', '#8a4a5b', '#f0d7dd'],
  ['#0d1826', '#4a6b8a', '#dbe8f5'],
  ['#0b1220', '#6b5b8a', '#ded6f0'],
  ['#12202c', '#1f4e7e', '#b9d6f2'],
]

function clipUrl(n) {
  if (n == null) return null
  const i = (Math.abs(Number(n) || 1) - 1) % CLIPS.length
  return CLIPS[i]
}

/** A deterministic, self-contained SVG poster. Encoded (not base64'd) so it
 *  stays small and readable, and so the `#` in every colour is escaped —
 *  adapters drop these straight into `url("…")` inside a CSS shorthand. */
function poster(cover, key, w = 720, h = 1280) {
  const [a, b, ink] = PALETTE[(Math.abs(Number(cover) || 1) - 1) % PALETTE.length]
  const r1 = seeded('a' + key), r2 = seeded('b' + key), r3 = seeded('c' + key)
  const cx = Math.round(w * (0.2 + r1 * 0.6))
  const cy = Math.round(h * (0.25 + r2 * 0.4))
  const rad = Math.round(Math.min(w, h) * (0.28 + r3 * 0.22))
  const rot = Math.round(r1 * 90 - 45)
  const rings = [0.55, 0.78, 1, 1.24, 1.5]
    .map((k, i) => `<circle cx="${cx}" cy="${cy}" r="${Math.round(rad * k)}" stroke-opacity="${(0.26 - i * 0.04).toFixed(2)}"/>`)
    .join('')
  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}">` +
    `<defs><linearGradient id="g" x1="0" y1="0" x2="0.7" y2="1">` +
    `<stop offset="0" stop-color="${a}"/><stop offset="1" stop-color="${b}"/></linearGradient></defs>` +
    `<rect width="${w}" height="${h}" fill="url(#g)"/>` +
    `<g fill="none" stroke="${ink}" stroke-width="2">${rings}</g>` +
    `<g fill="${ink}" fill-opacity="0.10" transform="rotate(${rot} ${cx} ${cy})">` +
    `<rect x="${cx - rad}" y="${cy - 3}" width="${rad * 2}" height="6" rx="3"/>` +
    `<rect x="${cx - 3}" y="${cy - rad}" width="6" height="${rad * 2}" rx="3"/></g>` +
    `<rect x="0" y="${h - 4}" width="${w}" height="4" fill="${ink}" fill-opacity="0.35"/>` +
    `</svg>`
  return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg)
}

const squareArt = (cover, key) => poster(cover, key, 480, 480)

/* Timestamps are anchored to ONE instant captured when this module loads,
   not to Date.now() per call. `util.agoIso()` re-reads the clock, which would
   make a row's createdAt drift by milliseconds between requests — and the reel
   feeds are cursor-paginated ON createdAt, so a drifting value means "load
   more" silently re-serves page 0. Same reason the day-bucket filter below can
   trust its own output. */
const BOOT = Date.now()
const at = (mins) => new Date(BOOT - (Number(mins) || 0) * 60000).toISOString().replace(/\.(\d{3})Z$/, '.$1Z')

const origin = () => (typeof window !== 'undefined' && window.location ? window.location.origin : '')

/* ---------------------------------------------------------------
   People. AuthorSummary is embedded in every feed row and comment,
   so it must resolve for all eight demo ids. The users domain wins
   when it is present; `storyTray` is the fallback index.
   --------------------------------------------------------------- */
function titleCase(s) {
  const t = String(s || '').replace(/^u-/, '')
  return t ? t[0].toUpperCase() + t.slice(1) : 'Member'
}

function people(db) {
  if (db.__people) return db.__people
  const idx = {}
  for (const p of db.storyTray || []) {
    idx[p.authorId] = {
      id: p.authorId,
      username: p.username || String(p.authorId).replace(/^u-/, ''),
      fullName: p.fullName || titleCase(p.authorId),
      profileImage: p.profileImage || null,
    }
  }
  // The users domain is authoritative for identity when it ships a list.
  const rows = Array.isArray(db.users) ? db.users : []
  for (const u of rows) {
    const id = u && (u.id || u.userId)
    if (!id) continue
    const prof = u.profile || {}
    idx[id] = {
      id,
      username: u.username || idx[id]?.username || String(id).replace(/^u-/, ''),
      fullName: prof.displayName || u.fullName
        || [u.fname, u.lname].filter(Boolean).join(' ').trim()
        || idx[id]?.fullName || titleCase(id),
      profileImage: prof.avatarUrl || u.avatarUrl || u.profileImage || idx[id]?.profileImage || null,
    }
  }
  db.__people = idx
  return idx
}

function author(db, id) {
  return people(db)[id] || {
    id, username: String(id).replace(/^u-/, ''), fullName: titleCase(id), profileImage: null,
  }
}

/** The signed-in id, however the auth fixture spells it. */
function meId(db) {
  return db?.me?.id || db?.currentUser?.id || db?.session?.user?.id || db?.auth?.me?.id || 'u-amina'
}

/** Stories and highlights are keyed on the eight demo people. When the demo
 *  account is somebody else, ITS OWN profile (and only its own) falls back to
 *  u-amina so "my stories" / "my highlights" are not empty. Every other id
 *  resolves strictly, so a stranger's profile still shows a stranger's data. */
function ownerKey(db, id, bucket) {
  if (bucket && bucket[id]) return id
  return String(id) === String(meId(db)) ? 'u-amina' : id
}

/* ---------------------------------------------------------------
   Reels
   --------------------------------------------------------------- */
const reelById = (db, id) => (db.reels || []).find(r => String(r.id) === String(id))

const soundById = (db, id) => (db.sounds || []).find(s => String(s.id) === String(id))

/** FeedItemResponse — what every reel LIST endpoint returns. */
function feedItem(db, r) {
  return {
    id: r.id,
    authorId: r.authorId,
    author: author(db, r.authorId),
    entityType: 'POST',
    postType: 'REEL',
    textPreview: r.caption,
    mediaUrl: poster(r.cover, r.id),      // cover / poster frame
    videoUrl: clipUrl(r.clip),            // REEL-only: the playable video
    reactionCount: r.reactionCount || 0,
    commentCount: r.commentCount || 0,
    viewCount: r.viewCount || 0,
    saveCount: r.saveCount || 0,
    shareCount: r.shareCount || 0,
    likedByMe: !!r.likedByMe,
    savedByMe: !!r.savedByMe,
    createdAt: at(r.minsAgo),
    // hydrateReels() builds through the legacy constructor → ranking is null
    source: null,
    rankScore: null,
    channel: null,
    channelPostId: null,
  }
}

/** PostResponse — the reel-detail re-hydration the viewer falls back to. */
function postResponse(db, r) {
  const s = soundById(db, r.soundId)
  return {
    id: r.id,
    authorId: r.authorId,
    author: author(db, r.authorId),
    postType: 'REEL',
    status: 'PUBLISHED',
    visibility: 'PUBLIC',
    textContent: r.caption,
    audioTrackUrl: s ? TONE : null,
    audioTrackName: s ? `${s.title} · ${s.artistName}` : null,
    locationName: null,
    locationLat: null,
    locationLng: null,
    sharedPostId: null,
    shareLink: shareToken(r.id),
    mediaUrls: [clipUrl(r.clip), poster(r.cover, r.id)],
    mediaTypes: ['VIDEO', 'IMAGE'],
    reactionCount: r.reactionCount || 0,
    commentCount: r.commentCount || 0,
    viewCount: r.viewCount || 0,
    saveCount: r.saveCount || 0,
    shareCount: r.shareCount || 0,
    likedByMe: !!r.likedByMe,
    savedByMe: !!r.savedByMe,
    createdAt: at(r.minsAgo),
    updatedAt: at(r.minsAgo),
    savedAt: null,
    savedCollectionName: null,
  }
}

function shareToken(id) {
  return String(id).replace(/[^a-z0-9]/gi, '').padEnd(12, '0').slice(0, 12)
}

/** Newest first, cursor = the createdAt of the last row of the previous page. */
function reelList(db, rows, query = {}) {
  const size = Number(query.pageSize ?? query.size ?? query.limit ?? 20) || 20
  const sorted = [...rows].sort((a, b) => (a.minsAgo || 0) - (b.minsAgo || 0))
  let from = 0
  if (query.cursor) {
    const idx = sorted.findIndex(r => at(r.minsAgo) === query.cursor)
    if (idx >= 0) from = idx + 1
  }
  return sorted.slice(from, from + size).map(r => feedItem(db, r))
}

/* ---------------------------------------------------------------
   Reel comments
   --------------------------------------------------------------- */
function commentResponse(db, c, postId) {
  return {
    id: c.id,
    postId,
    authorId: c.authorId,
    author: author(db, c.authorId),
    textContent: c.text,
    mediaUrl: null,
    mediaType: null,
    reactionCount: c.reactionCount || 0,
    replyCount: (c.replies || []).length,
    likedByMe: !!c.likedByMe,
    deleted: false,
    edited: false,
    createdAt: at(c.minsAgo),
  }
}

function replyResponse(db, rp, parentId, postId) {
  return {
    id: rp.id,
    parentId,
    postId,
    authorId: rp.authorId,
    author: author(db, rp.authorId),
    textContent: rp.text,
    mediaUrl: null,
    reactionCount: rp.reactionCount || 0,
    likedByMe: !!rp.likedByMe,
    deleted: false,
    edited: false,
    createdAt: at(rp.minsAgo),
  }
}

/** Locate a comment (and the reel it hangs under) by comment id. */
function findComment(db, commentId) {
  const map = db.reelComments || {}
  for (const postId of Object.keys(map)) {
    const c = (map[postId] || []).find(x => String(x.id) === String(commentId))
    if (c) return { postId, comment: c }
  }
  return null
}

/* ---------------------------------------------------------------
   Watch history — seeded lazily off the reel list so the "Watched
   reels" screen is inhabited without a second fixture key.
   --------------------------------------------------------------- */
function watched(db) {
  if (!db.__reelWatched) {
    db.__reelWatched = (db.reels || []).slice(0, 9).map((r, i) => ({
      id: `rv-${r.id}`,
      reelId: r.id,
      watchedSeconds: Math.max(3, Math.round((r.durationSeconds || 30) * (0.25 + seeded('w' + r.id) * 0.7))),
      minsAgo: 25 + i * 137,
    }))
  }
  return db.__reelWatched
}

function reelViewResponse(db, w) {
  const r = reelById(db, w.reelId)
  const a = r ? author(db, r.authorId) : null
  return {
    id: w.id,
    watchedSeconds: w.watchedSeconds || 0,
    reel: r ? {
      id: r.id,
      textPreview: r.caption,
      thumbnailUrl: poster(r.cover, r.id),
      mediaUrl: clipUrl(r.clip),
      durationSeconds: r.durationSeconds || null,
      // ReelViewResponse.AuthorSummary spells the avatar `avatarUrl`
      author: { id: a.id, username: a.username, fullName: a.fullName, avatarUrl: a.profileImage },
    } : null,
    watchedAt: at(w.minsAgo),
    // Server-rendered strings — left null so the client formats in its own
    // language rather than being handed an English one.
    timeAgo: null,
    formattedDate: null,
  }
}

/* ---------------------------------------------------------------
   Stories
   --------------------------------------------------------------- */

/** Frame types whose CONTENT IS THE TEXT. Both viewers render the caption only
 *  when the frame has no media (`item.text && !item.hasMedia` — StoryViewer.jsx
 *  and HighlightViewer.jsx), because a designed story has its words baked into
 *  the image and a second centred copy would double them. So a media URL on one
 *  of these frames does not merely add a backdrop: it DELETES the story. The
 *  backend agrees — `POST /stories {storyType:'TEXT'}` (ComposeModal's no-media
 *  path) stores mediaUrl null. */
const TEXT_FRAME = new Set(['TEXT', 'KNOWLEDGE_PILL'])

/** A story frame's media pair, from the fixture's `clip` / `cover` / `url`. */
function storyMedia(s) {
  if (s.url) return { mediaUrl: s.url, thumbnailUrl: s.thumbUrl || s.url }   // uploaded in-session
  // A stray `cover` on a text frame can never be allowed to hide the words.
  if (TEXT_FRAME.has(s.storyType)) return { mediaUrl: null, thumbnailUrl: null }
  if (s.clip != null) {
    return { mediaUrl: clipUrl(s.clip), thumbnailUrl: poster(s.cover, s.storyId, 360, 640) }
  }
  if (s.cover != null) {
    return { mediaUrl: poster(s.cover, s.storyId, 720, 1280), thumbnailUrl: poster(s.cover, s.storyId, 360, 640) }
  }
  return { mediaUrl: null, thumbnailUrl: null }
}

function storyEntity(db, authorId, s) {
  return {
    authorId,
    createdAt: at(s.minsAgo),
    storyId: s.storyId,
    storyType: s.storyType || 'IMAGE',
    visibility: s.visibility || 'PUBLIC',
    ...storyMedia(s),
    textContent: s.textContent || null,
    expiresAt: at(s.minsAgo - (s.lifetimeHours || 24) * 60),
  }
}

function findStory(db, storyId) {
  const map = db.stories || {}
  for (const authorId of Object.keys(map)) {
    const s = (map[authorId] || []).find(x => String(x.storyId) === String(storyId))
    if (s) return { authorId, story: s }
  }
  return null
}

function findPoll(db, pollId) {
  const map = db.stories || {}
  for (const authorId of Object.keys(map)) {
    for (const s of map[authorId] || []) {
      if (s.poll && String(s.poll.pollId) === String(pollId)) return { authorId, story: s, poll: s.poll }
    }
  }
  return null
}

function pollEntity(story, authorId) {
  const p = story.poll
  return {
    storyId: story.storyId,
    pollId: p.pollId,
    question: p.question,
    optionA: p.optionA,
    optionB: p.optionB,
    authorId,
    createdAt: at(story.minsAgo),
  }
}

/* ---------------------------------------------------------------
   Highlights
   --------------------------------------------------------------- */
function highlightEntity(authorId, h) {
  return {
    authorId,
    displayOrder: h.displayOrder ?? 0,
    highlightId: h.highlightId,
    title: h.title,
    coverUrl: poster(h.cover, h.highlightId, 480, 480),
    createdAt: at(h.minsAgo),
  }
}

function highlightStoryEntity(authorId, hid, s) {
  return {
    highlightId: hid,
    createdAt: at(s.minsAgo),
    storyId: s.storyId,
    authorId,
    storyType: s.storyType || 'IMAGE',
    ...storyMedia(s),
    textContent: s.textContent || null,
  }
}

function findHighlight(db, hid) {
  const map = db.highlights || {}
  for (const authorId of Object.keys(map)) {
    const h = (map[authorId] || []).find(x => String(x.highlightId) === String(hid))
    if (h) return { authorId, highlight: h }
  }
  return null
}

/* ---------------------------------------------------------------
   Sounds
   --------------------------------------------------------------- */
function soundEntity(db, s) {
  return {
    id: s.id,
    title: s.title,
    artistName: s.artistName,
    audioUrl: TONE,
    coverArtUrl: squareArt(s.cover, s.id),
    durationSeconds: s.durationSeconds ?? null,
    category: s.category,
    status: s.status || 'APPROVED',
    uploaderId: s.uploaderId || null,
    createdAt: at(s.minsAgo),
    updatedAt: at(s.minsAgo),
  }
}

function soundByCategoryEntity(db, s) {
  return {
    category: s.category,
    createdAt: at(s.minsAgo),
    soundId: s.id,
    title: s.title,
    artistName: s.artistName,
    audioUrl: TONE,
    coverArtUrl: squareArt(s.cover, s.id),
    durationSeconds: s.durationSeconds ?? null,
  }
}

/* =========================================================
   Routes — more specific patterns first.
   ========================================================= */
export const routes = [
  /* ---- reel feeds ---------------------------------------------------- */
  {
    m: 'GET', p: /^\/api\/v1\/posts\/reels\/for-you$/,
    fn: (db, { query }) => {
      // engagement × recency, the way ReelFeedService ranks it
      const scored = (db.reels || []).map(r => ({
        r,
        s: ((r.reactionCount || 0) * 3 + (r.commentCount || 0) * 2 + (r.viewCount || 0))
           / (1 + (r.minsAgo || 0) / 720),
      })).sort((a, b) => b.s - a.s).map(x => x.r)
      const size = Number(query.pageSize ?? query.size ?? 20) || 20
      return scored.slice(0, size).map(r => feedItem(db, r))
    },
  },
  {
    m: 'GET', p: /^\/api\/v1\/posts\/reels\/following$/,
    fn: (db, { query }) => {
      const mine = meId(db)
      return reelList(db, (db.reels || []).filter(r => String(r.authorId) !== String(mine)), query)
    },
  },
  {
    m: 'GET', p: /^\/api\/v1\/posts\/reels\/by-author\/([^/]+)$/,
    fn: (db, { params, query }) =>
      reelList(db, (db.reels || []).filter(r => String(r.authorId) === String(params[0])), query),
  },
  {
    // canonical /posts/reels + legacy alias /posts/feed/reels; day-bucketed
    m: 'GET', p: /^\/api\/v1\/posts\/(?:feed\/)?reels$/,
    fn: (db, { query }) => {
      const rows = query.day
        ? (db.reels || []).filter(r => at(r.minsAgo).slice(0, 10) === String(query.day))
        : (db.reels || [])
      return reelList(db, rows, query)
    },
  },

  /* ---- reel watch history (activity module) --------------------------- */
  {
    m: 'POST', p: /^\/api\/v1\/posts\/([^/]+)\/reels\/view$/,
    fn: (db, { params, body }) => {
      const r = reelById(db, params[0])
      if (!r) throw mockError(404, 'NOT_FOUND', 'Reel not found')
      const secs = Number(body?.watchedSeconds || 0) || 0
      const list = watched(db)
      const row = { id: `rv-${r.id}-${list.length}`, reelId: r.id, watchedSeconds: secs, minsAgo: 0 }
      list.unshift(row)
      return reelViewResponse(db, row)
    },
  },
  {
    m: 'GET', p: /^\/api\/v1\/users\/me\/reels\/watched$/,
    fn: (db, { query }) => {
      const rows = [...watched(db)].sort((a, b) => a.minsAgo - b.minsAgo).map(w => reelViewResponse(db, w))
      return page(rows, paging(query))
    },
  },
  {
    m: 'DELETE', p: /^\/api\/v1\/users\/me\/reels\/watched\/([^/]+)$/,
    fn: (db, { params }) => {
      const list = watched(db)
      // `ix`, not `at` — `at()` is the module's timestamp helper and shadowing
      // it inside a handler is a trap for the next edit in this function.
      const ix = list.findIndex(w => String(w.id) === String(params[0]))
      if (ix >= 0) list.splice(ix, 1)
      return null
    },
  },
  {
    m: 'DELETE', p: /^\/api\/v1\/users\/me\/reels\/watched$/,
    fn: (db) => {
      const n = watched(db).length
      db.__reelWatched = []
      return { deleted: n }
    },
  },

  /* ---- reel detail + engagement --------------------------------------
     Anchored on the `r-` id prefix so these never shadow the posts
     domain's generic /posts/{id} handlers (and vice-versa). */
  {
    m: 'GET', p: /^\/api\/v1\/posts\/(r-[^/]+)\/comments$/,
    fn: (db, { params, query }) => {
      const rows = (db.reelComments || {})[params[0]] || []
      const size = Number(query.pageSize ?? query.size ?? 20) || 20
      return [...rows]
        .sort((a, b) => b.minsAgo - a.minsAgo)
        .slice(0, size)
        .map(c => commentResponse(db, c, params[0]))
    },
  },
  {
    m: 'POST', p: /^\/api\/v1\/posts\/(r-[^/]+)\/comments$/,
    fn: (db, { params, body }) => {
      const r = reelById(db, params[0])
      if (!r) throw mockError(404, 'NOT_FOUND', 'Reel not found')
      const text = String(body?.text || '').trim()
      if (!text) throw mockError(400, 'VALIDATION_ERROR', 'text is required')
      db.reelComments = db.reelComments || {}
      const list = db.reelComments[params[0]] || (db.reelComments[params[0]] = [])
      const c = {
        id: `rc-${params[0]}-${list.length + 1}-${Date.now().toString(36)}`,
        authorId: meId(db), minsAgo: 0, reactionCount: 0, likedByMe: false,
        text, replies: [],
      }
      list.push(c)
      r.commentCount = (r.commentCount || 0) + 1
      return commentResponse(db, c, params[0])
    },
  },
  {
    m: 'GET', p: /^\/api\/v1\/posts\/comments\/(rc-[^/]+)\/replies$/,
    fn: (db, { params }) => {
      const found = findComment(db, params[0])
      if (!found) throw mockError(404, 'NOT_FOUND', 'Comment not found')
      return (found.comment.replies || [])
        .slice()
        .sort((a, b) => b.minsAgo - a.minsAgo)
        .map(rp => replyResponse(db, rp, found.comment.id, found.postId))
    },
  },
  {
    m: 'POST', p: /^\/api\/v1\/posts\/comments\/(rc-[^/]+)\/replies$/,
    fn: (db, { params, body }) => {
      const found = findComment(db, params[0])
      if (!found) throw mockError(404, 'NOT_FOUND', 'Comment not found')
      const text = String(body?.text || '').trim()
      if (!text) throw mockError(400, 'VALIDATION_ERROR', 'text is required')
      const replies = found.comment.replies || (found.comment.replies = [])
      const rp = {
        id: `rr-${found.comment.id}-${replies.length + 1}`,
        authorId: meId(db), minsAgo: 0, reactionCount: 0, likedByMe: false, text,
      }
      replies.push(rp)
      const reel = reelById(db, found.postId)
      if (reel) reel.commentCount = (reel.commentCount || 0) + 1
      return replyResponse(db, rp, found.comment.id, found.postId)
    },
  },
  {
    m: 'POST', p: /^\/api\/v1\/posts\/(r-[^/]+)\/comments\/([^/]+)\/reactions$/,
    fn: (db, { params }) => {
      const found = findComment(db, params[1])
      const c = found?.comment
      if (!c) throw mockError(404, 'NOT_FOUND', 'Comment not found')
      c.likedByMe = !c.likedByMe
      c.reactionCount = Math.max(0, (c.reactionCount || 0) + (c.likedByMe ? 1 : -1))
      // toggleCommentReaction answers {commentId, userId, liked} — no postId.
      return { commentId: params[1], userId: meId(db), liked: c.likedByMe }
    },
  },
  {
    m: 'DELETE', p: /^\/api\/v1\/posts\/(r-[^/]+)\/comments\/([^/]+)\/reactions$/,
    fn: (db, { params }) => {
      const c = findComment(db, params[1])?.comment
      if (c && c.likedByMe) { c.likedByMe = false; c.reactionCount = Math.max(0, (c.reactionCount || 0) - 1) }
      return { commentId: params[1], liked: false }        // 200 {commentId, liked:false}
    },
  },
  {
    m: 'POST', p: /^\/api\/v1\/posts\/(r-[^/]+)\/reactions$/,
    fn: (db, { params }) => {
      const r = reelById(db, params[0])
      if (!r) throw mockError(404, 'NOT_FOUND', 'Reel not found')
      r.likedByMe = !r.likedByMe
      r.reactionCount = Math.max(0, (r.reactionCount || 0) + (r.likedByMe ? 1 : -1))
      return { postId: r.id, userId: meId(db), liked: r.likedByMe }
    },
  },
  {
    m: 'DELETE', p: /^\/api\/v1\/posts\/(r-[^/]+)\/reactions$/,
    fn: (db, { params }) => {
      const r = reelById(db, params[0])
      if (r && r.likedByMe) { r.likedByMe = false; r.reactionCount = Math.max(0, (r.reactionCount || 0) - 1) }
      return { postId: params[0], liked: false }            // 200 {postId, liked:false}
    },
  },
  {
    m: 'GET', p: /^\/api\/v1\/posts\/(r-[^/]+)\/reactions\/me$/,
    fn: (db, { params }) => ({ postId: params[0], userId: meId(db), liked: !!reelById(db, params[0])?.likedByMe }),
  },
  {
    m: 'POST', p: /^\/api\/v1\/posts\/(r-[^/]+)\/saves$/,
    fn: (db, { params }) => {
      const r = reelById(db, params[0])
      if (!r) throw mockError(404, 'NOT_FOUND', 'Reel not found')
      r.savedByMe = !r.savedByMe
      r.saveCount = Math.max(0, (r.saveCount || 0) + (r.savedByMe ? 1 : -1))
      return { postId: r.id, userId: meId(db), saved: r.savedByMe }
    },
  },
  {
    m: 'DELETE', p: /^\/api\/v1\/posts\/(r-[^/]+)\/saves$/,
    fn: (db, { params }) => {
      const r = reelById(db, params[0])
      if (r && r.savedByMe) { r.savedByMe = false; r.saveCount = Math.max(0, (r.saveCount || 0) - 1) }
      return { postId: params[0], userId: meId(db), saved: false }
    },
  },
  {
    m: 'GET', p: /^\/api\/v1\/posts\/(r-[^/]+)\/saves\/me$/,
    fn: (db, { params }) => ({ postId: params[0], userId: meId(db), saved: !!reelById(db, params[0])?.savedByMe }),
  },
  {
    m: 'POST', p: /^\/api\/v1\/posts\/(r-[^/]+)\/views$/,
    fn: (db, { params }) => {
      const r = reelById(db, params[0])
      if (!r) throw mockError(404, 'NOT_FOUND', 'Reel not found')
      // idempotent per viewer, exactly like the real endpoint
      db.__reelViewed = db.__reelViewed || {}
      const counted = !db.__reelViewed[r.id]
      if (counted) { db.__reelViewed[r.id] = true; r.viewCount = (r.viewCount || 0) + 1 }
      return { postId: r.id, userId: meId(db), counted, viewCount: r.viewCount || 0 }
    },
  },
  {
    m: 'GET', p: /^\/api\/v1\/posts\/(r-[^/]+)\/share-link$/,
    fn: (db, { params }) => {
      const r = reelById(db, params[0])
      if (!r) throw mockError(404, 'NOT_FOUND', 'Reel not found')
      const token = shareToken(r.id)
      return {
        shortUrl: `${origin()}/p/${token}`,
        canonicalUrl: `${origin()}/reels/${r.id}`,
        token,
        shareCount: r.shareCount || 0,
      }
    },
  },
  {
    m: 'POST', p: /^\/api\/v1\/posts\/(r-[^/]+)\/share$/,
    fn: (db, { params }) => {
      const r = reelById(db, params[0])
      if (!r) throw mockError(404, 'NOT_FOUND', 'Reel not found')
      r.shareCount = (r.shareCount || 0) + 1
      const token = shareToken(r.id)
      return {
        shortUrl: `${origin()}/p/${token}`,
        canonicalUrl: `${origin()}/reels/${r.id}`,
        token,
        shareCount: r.shareCount,
      }
    },
  },
  {
    m: 'GET', p: /^\/api\/v1\/posts\/(r-[^/]+)$/,
    fn: (db, { params }) => {
      const r = reelById(db, params[0])
      if (!r) throw mockError(404, 'NOT_FOUND', 'Reel not found')
      return postResponse(db, r)
    },
  },

  /* ---- stories ------------------------------------------------------- */
  {
    m: 'GET', p: /^\/api\/v1\/stories\/by-author\/([^/]+)$/,
    fn: (db, { params }) => {
      const key = ownerKey(db, params[0], db.stories || {})
      const rows = (db.stories || {})[key] || []
      return [...rows]
        .sort((a, b) => a.minsAgo - b.minsAgo)     // createdAt DESC
        .map(s => storyEntity(db, key, s))
    },
  },
  {
    m: 'POST', p: /^\/api\/v1\/stories$/,
    fn: (db, { body }) => {
      const fd = typeof FormData !== 'undefined' && body instanceof FormData
      const field = (k) => (fd ? body.get(k) : body?.[k])
      /* The composer posts multipart with the flattened PNG (or the raw file)
         in `media`; the JSON path posts a TEXT story with no media at all.
         A blob: URL is the honest stand-in for the R2 upload — it is what the
         real response's mediaUrl behaves like (an absolute, playable URL the
         adapters pass through untouched), and it means the frame the user just
         composed is the frame they see. */
      const blobOf = (k) => {
        const f = field(k)
        return (f && typeof Blob !== 'undefined' && f instanceof Blob && typeof URL !== 'undefined')
          ? URL.createObjectURL(f) : null
      }
      const mine = ownerKey(db, meId(db), db.stories || {})
      db.stories = db.stories || {}
      const list = db.stories[mine] || (db.stories[mine] = [])
      const url = blobOf('media') || (typeof field('mediaUrl') === 'string' ? field('mediaUrl') : null)
      const thumbUrl = blobOf('thumbnail') || (typeof field('thumbnailUrl') === 'string' ? field('thumbnailUrl') : null)
      const s = {
        storyId: `s-new-${Date.now().toString(36)}`,
        storyType: String(field('storyType') || 'IMAGE'),
        visibility: String(field('visibility') || 'PUBLIC'),
        // No poster is invented: a story with no media part is a TEXT frame,
        // and storyMedia() answers nulls for it exactly as the backend does.
        cover: null,
        clip: null,
        url,
        thumbUrl,
        minsAgo: 0,
        lifetimeHours: Number(field('lifetimeHours') || 24) || 24,
        textContent: field('textContent') || null,
        views: [],
      }
      list.unshift(s)
      return storyEntity(db, mine, s)
    },
  },
  {
    m: 'POST', p: /^\/api\/v1\/stories\/([^/]+)\/views$/,
    fn: (db, { params }) => {
      const found = findStory(db, params[0])
      if (!found) throw mockError(404, 'NOT_FOUND', 'Story not found')
      const me = meId(db)
      const views = found.story.views || (found.story.views = [])
      if (!views.some(v => String(v.viewerId) === String(me))) views.unshift({ viewerId: me, minsAgo: 0 })
      return null                                   // 202 Accepted, no body
    },
  },
  {
    m: 'GET', p: /^\/api\/v1\/stories\/([^/]+)\/views$/,
    fn: (db, { params, query }) => {
      const found = findStory(db, params[0])
      if (!found) throw mockError(404, 'NOT_FOUND', 'Story not found')
      const size = Number(query.pageSize ?? 50) || 50
      return [...(found.story.views || [])]
        .sort((a, b) => a.minsAgo - b.minsAgo)
        .slice(0, size)
        .map(v => ({ storyId: params[0], viewedAt: at(v.minsAgo), viewerId: v.viewerId }))
    },
  },
  {
    m: 'GET', p: /^\/api\/v1\/stories\/([^/]+)\/poll$/,
    fn: (db, { params }) => {
      const found = findStory(db, params[0])
      // No poll on this frame is a genuine 404 on the real controller.
      if (!found || !found.story.poll) throw mockError(404, 'NOT_FOUND', 'No poll on this story')
      return pollEntity(found.story, found.authorId)
    },
  },
  {
    m: 'POST', p: /^\/api\/v1\/stories\/([^/]+)\/poll$/,
    fn: (db, { params, body }) => {
      const found = findStory(db, params[0])
      if (!found) throw mockError(404, 'NOT_FOUND', 'Story not found')
      found.story.poll = {
        pollId: `p-new-${Date.now().toString(36)}`,
        question: body?.question || '',
        optionA: body?.optionA || '',
        optionB: body?.optionB || '',
        voteA: 0, voteB: 0, myChoice: null, voters: { A: [], B: [] },
      }
      return pollEntity(found.story, found.authorId)
    },
  },
  {
    m: 'DELETE', p: /^\/api\/v1\/stories\/([^/]+)$/,
    fn: (db, { params }) => {
      const found = findStory(db, params[0])
      if (!found) throw mockError(404, 'NOT_FOUND', 'Story not found')
      const list = db.stories[found.authorId]
      list.splice(list.indexOf(found.story), 1)
      return null
    },
  },

  /* ---- story polls ---------------------------------------------------- */
  {
    m: 'POST', p: /^\/api\/v1\/polls\/([^/]+)\/vote$/,
    fn: (db, { params, query }) => {
      const found = findPoll(db, params[0])
      if (!found) throw mockError(404, 'NOT_FOUND', 'Poll not found')
      const choice = String(query.choice || '').toUpperCase()
      if (choice !== 'A' && choice !== 'B') throw mockError(400, 'VALIDATION_ERROR', 'Choice must be A or B')
      const p = found.poll
      const me = meId(db)
      p.voters = p.voters || { A: [], B: [] }
      if (p.myChoice && p.myChoice !== choice) {
        // switching sides: decrement the old counter and drop the old voter row
        p[p.myChoice === 'A' ? 'voteA' : 'voteB'] = Math.max(0, (p.myChoice === 'A' ? p.voteA : p.voteB) - 1)
        p.voters[p.myChoice] = (p.voters[p.myChoice] || []).filter(v => String(v.voterId) !== String(me))
      }
      if (p.myChoice !== choice) {
        p[choice === 'A' ? 'voteA' : 'voteB'] = (choice === 'A' ? p.voteA : p.voteB) + 1
        p.voters[choice] = [{ voterId: me, minsAgo: 0 }, ...(p.voters[choice] || [])]
        p.myChoice = choice
      }
      return { choice, voteA: p.voteA || 0, voteB: p.voteB || 0 }
    },
  },
  {
    m: 'GET', p: /^\/api\/v1\/polls\/([^/]+)\/vote\/me$/,
    fn: (db, { params }) => {
      const found = findPoll(db, params[0])
      if (!found) return { pollId: params[0], voterId: meId(db), choice: null }
      return {
        pollId: params[0],
        voterId: meId(db),
        choice: found.poll.myChoice || null,
        votedAt: found.poll.myChoice ? at(0) : null,
      }
    },
  },
  {
    m: 'GET', p: /^\/api\/v1\/polls\/([^/]+)\/results$/,
    fn: (db, { params }) => {
      const found = findPoll(db, params[0])
      if (!found) throw mockError(404, 'NOT_FOUND', 'Poll not found')
      // results() calls readCounts(pollId, null) → `choice` is null here
      return { choice: null, voteA: found.poll.voteA || 0, voteB: found.poll.voteB || 0 }
    },
  },
  {
    m: 'GET', p: /^\/api\/v1\/polls\/([^/]+)\/voters\/([^/]+)$/,
    fn: (db, { params, query }) => {
      const found = findPoll(db, params[0])
      if (!found) throw mockError(404, 'NOT_FOUND', 'Poll not found')
      const choice = String(params[1]).toUpperCase()
      const size = Number(query.pageSize ?? 50) || 50
      return [...((found.poll.voters || {})[choice] || [])]
        .sort((a, b) => a.minsAgo - b.minsAgo)
        .slice(0, size)
        .map(v => ({ pollId: params[0], choice, votedAt: at(v.minsAgo), voterId: v.voterId }))
    },
  },

  /* ---- highlights ----------------------------------------------------- */
  {
    m: 'PATCH', p: /^\/api\/v1\/highlights\/order$/,
    fn: (db, { body }) => {
      const mine = ownerKey(db, meId(db), db.highlights || {})
      const list = (db.highlights || {})[mine] || []
      const order = Array.isArray(body?.order) ? body.order.map(String) : []
      // foreign / unknown ids are silently skipped, exactly like the service
      const ranked = order.map(id => list.find(h => String(h.highlightId) === id)).filter(Boolean)
      const rest = list.filter(h => !ranked.includes(h))
      const next = [...ranked, ...rest]
      next.forEach((h, i) => { h.displayOrder = i })
      db.highlights[mine] = next
      return next.map(h => highlightEntity(mine, h))
    },
  },
  {
    m: 'GET', p: /^\/api\/v1\/highlights\/by-author\/([^/]+)$/,
    fn: (db, { params }) => {
      const key = ownerKey(db, params[0], db.highlights || {})
      return [...((db.highlights || {})[key] || [])]
        .sort((a, b) => (a.displayOrder ?? 0) - (b.displayOrder ?? 0))
        .map(h => highlightEntity(key, h))
    },
  },
  {
    m: 'POST', p: /^\/api\/v1\/highlights$/,
    fn: (db, { body }) => {
      const mine = ownerKey(db, meId(db), db.highlights || {})
      db.highlights = db.highlights || {}
      const list = db.highlights[mine] || (db.highlights[mine] = [])
      const h = {
        highlightId: `h-new-${Date.now().toString(36)}`,
        displayOrder: body?.displayOrder ?? list.length,
        cover: 1 + (list.length % PALETTE.length),
        minsAgo: 0,
        title: body?.title || '',
        stories: [],
      }
      list.push(h)
      return highlightEntity(mine, h)
    },
  },
  {
    m: 'GET', p: /^\/api\/v1\/highlights\/([^/]+)\/stories$/,
    fn: (db, { params }) => {
      const found = findHighlight(db, params[0])
      if (!found) throw mockError(404, 'NOT_FOUND', 'Highlight not found')
      return [...(found.highlight.stories || [])]
        .sort((a, b) => b.minsAgo - a.minsAgo)      // createdAt ASC
        .map(s => highlightStoryEntity(found.authorId, params[0], s))
    },
  },
  {
    m: 'POST', p: /^\/api\/v1\/highlights\/([^/]+)\/stories\/([^/]+)$/,
    fn: (db, { params }) => {
      const found = findHighlight(db, params[0])
      if (!found) throw mockError(404, 'NOT_FOUND', 'Highlight not found')
      const src = findStory(db, params[1])
      if (!src) throw mockError(404, 'NOT_FOUND', 'Story not found')
      const stories = found.highlight.stories || (found.highlight.stories = [])
      if (stories.some(s => String(s.storyId) === String(params[1]))) {
        return highlightStoryEntity(found.authorId, params[0], stories.find(s => String(s.storyId) === String(params[1])))
      }
      // the snapshot is DENORMALIZED — the source row vanishes at the TTL
      const snap = {
        storyId: src.story.storyId,
        storyType: src.story.storyType,
        cover: src.story.cover ?? null,
        clip: src.story.clip ?? null,
        url: src.story.url || null,
        thumbUrl: src.story.thumbUrl || null,
        minsAgo: src.story.minsAgo,
        textContent: src.story.textContent || null,
      }
      stories.push(snap)
      return highlightStoryEntity(found.authorId, params[0], snap)
    },
  },
  {
    m: 'DELETE', p: /^\/api\/v1\/highlights\/([^/]+)\/stories\/([^/]+)$/,
    fn: (db, { params }) => {
      const found = findHighlight(db, params[0])
      if (!found) throw mockError(404, 'NOT_FOUND', 'Highlight not found')
      const stories = found.highlight.stories || []
      const ix = stories.findIndex(s => String(s.storyId) === String(params[1]))   // not `at` — see above
      if (ix >= 0) stories.splice(ix, 1)
      return null
    },
  },

  /* ---- sounds --------------------------------------------------------- */
  {
    m: 'GET', p: /^\/api\/v1\/sounds\/search$/,
    fn: (db, { query }) => {
      const q = String(query.q || '').trim().toLowerCase()
      if (!q) return []                              // blank q → [] (use the category browser)
      const limit = Number(query.limit ?? 20) || 20
      return (db.sounds || [])
        .filter(s => s.status === 'APPROVED')
        .filter(s => !query.category || s.category === query.category)
        .filter(s => `${s.title} ${s.artistName}`.toLowerCase().includes(q))
        .sort((a, b) => (b.useCount || 0) - (a.useCount || 0))
        .slice(0, limit)
        .map(s => soundEntity(db, s))
    },
  },
  {
    m: 'GET', p: /^\/api\/v1\/sounds\/by-category\/([^/]+)$/,
    fn: (db, { params, query }) => {
      const size = Number(query.pageSize ?? 20) || 20
      return (db.sounds || [])
        .filter(s => s.category === params[0] && s.status === 'APPROVED')
        .sort((a, b) => a.minsAgo - b.minsAgo)
        .slice(0, size)
        .map(s => soundByCategoryEntity(db, s))
    },
  },
  {
    m: 'GET', p: /^\/api\/v1\/sounds\/([^/]+)\/posts$/,
    fn: (db, { params, query }) => {
      const size = Number(query.pageSize ?? 20) || 20
      return (db.reels || [])
        .filter(r => String(r.soundId) === String(params[0]))
        .sort((a, b) => a.minsAgo - b.minsAgo)
        .slice(0, size)
        .map(r => ({ soundId: params[0], createdAt: at(r.minsAgo), postId: r.id, authorId: r.authorId }))
    },
  },
  {
    m: 'GET', p: /^\/api\/v1\/sounds\/([^/]+)\/usage$/,
    fn: (db, { params }) => {
      const s = soundById(db, params[0])
      const used = (db.reels || []).filter(r => String(r.soundId) === String(params[0])).length
      return { soundId: params[0], useCount: (s?.useCount || 0) + used }
    },
  },
  {
    m: 'POST', p: /^\/api\/v1\/sounds$/,
    fn: (db, { body }) => {
      db.sounds = db.sounds || []
      const s = {
        id: `snd-new-${Date.now().toString(36)}`,
        title: body?.title || '',
        artistName: body?.artistName || '',
        durationSeconds: body?.durationSeconds ?? null,
        category: body?.category || 'ORIGINAL',
        status: 'PENDING_REVIEW',                    // autoApprove is admin-only
        uploaderId: meId(db),
        minsAgo: 0,
        useCount: 0,
        cover: 1 + (db.sounds.length % PALETTE.length),
      }
      db.sounds.push(s)
      return soundEntity(db, s)
    },
  },
  {
    m: 'GET', p: /^\/api\/v1\/sounds\/([^/]+)$/,
    fn: (db, { params }) => {
      const s = soundById(db, params[0])
      if (!s) throw mockError(404, 'NOT_FOUND', 'Sound not found')
      return soundEntity(db, s)
    },
  },
]
